insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ae8c1d6-4a69-4a78-8255-8f7a954e4608', 'fr', 'Dans un café, tu fais une remarque sur la longue file d’attente. Elle sourit, répond par une blague et se tourne vers toi.', '["Elle est courtoise parce que tu as parlé en premier", "Elle est ouverte et prête à continuer", "Elle passe le temps en attendant"]'::jsonb, 'L’humour et le fait de se tourner vers toi montrent qu’elle s’implique. Elle participe, elle ne se contente pas de répondre.')
