insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fb3d329-54bd-4b72-a37a-6435bb2ff6a4', 'fr', 'Tu fais une remarque sur le temps qu’il faut pour être servi. Elle sourit et approuve avec enthousiasme.', '["Elle est agacée et se défoule, sans être forcément intéressée", "Elle teste si tu vas approuver ses plaintes", "Elle te renvoie ton énergie et reste dans l’échange"]'::jsonb, 'Une réponse enthousiaste qui prolonge le sujet montre qu’elle s’implique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a02bd67f-f7f7-4331-a001-13bf4277f3f7', 'fr', 'Pourquoi commencer par « J’ai une question » marche-t-il mieux que de poser directement la question ?', '["Ça montre du respect en demandant la permission avant de prendre de son temps", "Ça crée de l’attente et de la curiosité avant la vraie question", "Ça lui laisse le temps de se préparer à échanger"]'::jsonb, 'Annoncer la question crée d’abord de la curiosité. Une question directe ne crée pas d’attente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a08ba78a-da12-481b-ae11-9fc1b34e1ee4', 'fr', 'Quelle est l’idée clé sur la façon dont les liens se créent ?', '["Quelqu’un doit accepter de parler en premier", "Ils arrivent par magie, sans effort", "Attendre mène toujours à de meilleurs résultats", "Le silence invite à des relations plus profondes"]'::jsonb, 'Chacun de tes amis existe parce que l’un de vous deux a ouvert la bouche en premier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0996b03-70aa-45f2-8b9b-1e136e46396e', 'fr', 'Tu commences par une remarque sur la situation. Elle rit et ajoute un détail de son côté. Et ensuite ?', '["Passer à un compliment direct", "Rester sur le sujet et l’approfondir un peu", "Lui demander tout de suite son numéro", "La taquiner pour jouer"]'::jsonb, 'Sa contribution montre qu’elle s’implique. Approfondir garde un élan naturel.')
