insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2802fe7-bfee-46b8-9b7a-3b8797515730', 'fr', 'Au café, elle te renvoie la balle. Le barista appelle son prénom. Elle dit : « Oh, c’est moi, pardon ! » Qu’est-ce que c’est ?', '["Une ouverture interrompue : propose vite de vous asseoir ensemble", "Politesse : elle s’est servie de sa commande comme d’une sortie pratique", "Une interruption extérieure, pas un signal : vois si elle revient après avoir récupéré sa boisson"]'::jsonb, 'Elle était impliquée avant l’interruption ; vois si elle revient ensuite.')
