insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ad29d82a-7cad-4f44-8cd0-826bc8d6d751', 'fr', 'À une soirée, un homme reste silencieux pendant que les autres font connaissance. Qu’est-ce qui lui manque ?', '["Un meilleur timing", "Du statut social", "Des amis à qui parler", "L’envie d’aller vers les autres"]'::jsonb, 'Engager la conversation est le geste simple qui crée du lien.')
