insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ae78311f-d702-432d-971c-a612871a0e09', 'fr', 'Elle t’adresse un léger sourire, puis se détourne. Que suggère la règle des 3 secondes ?', '["Analyser son sourire pour mesurer son intérêt", "Attendre un signe plus clair avant de bouger", "L’aborder tout de suite, avant que la réflexion ne s’emballe", "Préparer d’abord soigneusement tes mots"]'::jsonb, 'Agir vite court-circuite la liste de raisons de ne pas y aller que ton cerveau allonge sans cesse.')
