insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b147a697-dedb-4919-b533-e070ef0767f6', 'fr', 'Qu’est-ce qui évite de déclencher des réactions automatiques face à une menace ?', '["Arriver par un angle visible", "Ne pas bloquer son passage ni ses mouvements", "T’arrêter à une distance respectueuse", "Toutes les réponses ci-dessus"]'::jsonb, 'Respecter l’espace personnel rend l’échange calme et naturel.')
