insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b58b39df-93ba-4f7a-bed5-8eaaa5aa7a37', 'fr', 'Elle danse avec ses amies. Vos regards se croisent et elle sourit. Que fais-tu ?', '["Attendre qu’elle fasse une pause pour l’aborder", "Te mettre à danser près d’elle", "Croiser encore son regard avant de bouger", "L’aborder, elle et son groupe"]'::jsonb, 'Le soir, tout change vite : le moindre délai transforme les signaux en occasions manquées.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ec6ba9-5bbb-4681-a239-50a711d681dd', 'fr', 'Pourquoi les accroches sur un débat ou une dispute marchent-elles si bien ?', '["Elles créent un conflit joueur qui fait monter la tension sexuelle", "Elles font intervenir son avis pour trancher une question, ce qui lui donne de l’importance", "Elles montrent ta preuve sociale (tu discutais avec un ami)"]'::jsonb, 'Un débat ou un dilemme sollicite son avis, ce qui la valorise et l’implique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b723c51c-c180-4bd0-900c-be66fdc3c190', 'fr', 'Quelle est la plus grande différence entre politesse et ouverture ?', '["Le ton de la voix", "La fréquence des sourires", "Le niveau d’investissement réciproque", "La proximité physique"]'::jsonb, 'L’ouverture implique participation et curiosité ; la politesse sert à garder les choses fluides.')
