insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b765cb2c-14d9-49bf-b793-eeb611ababea', 'fr', 'Que se passe-t-il quand tu n’abordes que dans des conditions parfaites ?', '["Chaque approche paraît plus risquée parce qu’elle est rare", "Tu abordes beaucoup moins qu’en allant régulièrement vers les autres", "La qualité de tes approches s’améliore grâce à ta sélection"]'::jsonb, 'Attendre des conditions parfaites réduit la quantité d’approches et augmente la pression sur chacune.')
