insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b76c6af0-9df1-46cb-92cc-9c07b2d1404f', 'fr', 'Qu’est-ce qui rend une limite de temps efficace pour réduire la pression ?', '["Elle sait qu’elle n’est pas coincée dans une conversation sans fin avec un inconnu", "Ça montre que tu respectes son temps et que tu ne vas pas le lui faire perdre", "Moins de temps veut dire moins de risque de refus gênant"]'::jsonb, 'Annoncer que tu ne vas pas rester longtemps réduit la pression ; fais-le dès le début.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b86940dc-da66-4fd6-a19f-bbbca988a036', 'fr', 'Quels ajustements physiques évitent d’afficher ton anxiété ?', '["Marcher d’un pas régulier, ni pressé ni hésitant", "Garder les épaules en arrière et basses, ni remontées ni voûtées", "Fixer la femme qui t’intéresse pour montrer ta concentration et ton intention"]'::jsonb, 'Un pas régulier et des épaules relâchées réduisent la tension visible avant que tu parles.')
