insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ba3e426f-7282-4d49-a10f-46c3512816fc', 'fr', 'Elle répond de façon neutre, tu fais un geste clair, et elle dit non. Que fais-tu ensuite ?', '["La remercier et partir calmement", "Reformuler et réessayer", "Justifier ton intérêt", "Changer de sujet"]'::jsonb, 'Un refus pose une limite claire ; accepte-le calmement et pars avec sang-froid.')
