insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb7584e8-d1df-4dc9-a2bf-59a289ba6852', 'fr', 'Que se passe-t-il quand tu te contentes de réagir au lieu de donner la direction ?', '["L’échange avait besoin de plus de temps avant d’avancer", "Tu lui laisses le ton, et ce n’est pas elle qui fera avancer les choses à ta place", "Le timing s’améliore avant d’aller plus loin"]'::jsonb, 'Quand tu arrêtes de mener, l’élan retombe ; prends l’initiative de faire avancer l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc490fe2-1fae-42f6-b95e-718da8dccc05', 'fr', 'Pourquoi lire tôt les signaux est-il essentiel pour un échange respectueux ?', '["Son comportement de départ montre quelle marge tu as pour continuer", "Les femmes ont besoin de se sentir en sécurité avant de montrer leur intérêt", "Les premiers signaux t’évitent de franchir des limites qu’elle n’a pas ouvertes", "Toutes les réponses ci-dessus"]'::jsonb, 'Son confort passe en premier ; sers-toi des signaux pour décider de continuer ou de lever le pied.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc5cb121-8a63-45f6-8e11-7d46e1ff9ec2', 'fr', 'Quels traits renforcent la posture d’un homme ?', '["Une conviction claire en lui-même", "Être à l’aise avec le refus", "Donner la direction", "Chercher la validation"]'::jsonb, 'Une conviction claire en soi et le fait de mener renforcent la posture ; évite les comportements qui cherchent l’approbation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c1dd9ccd-317b-4320-a1f4-5bbb6553f846', 'fr', 'Tu l’abordes. Elle sourit, se tourne vers toi et demande « Quoi de neuf ? » d’un ton chaleureux.', '["Ouverture : elle est réceptive ; continue de construire l’échange", "Politesse : elle est aimable ; teste d’abord avec une phrase de plus", "Pas clair : il te faut plus d’éléments avant de juger son intérêt"]'::jsonb, 'Quand elle s’investit par des questions et une posture ouverte, l’intérêt est là ; garde l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c229e235-368e-47aa-9571-c1345d6402cf', 'fr', 'Tu abordes une femme dans un café. Quelle accroche peut la valoriser ?', '["« Salut, tu viens souvent ici ? »", "« J’ai besoin d’un avis féminin sur un truc. »", "« Tu bois quoi ? »", "« Tu es jolie aujourd’hui. »"]'::jsonb, 'Solliciter clairement son jugement lui donne un rôle plus important et suscite son implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c321230f-a277-4593-bdeb-01167899a30c', 'fr', 'Au supermarché, tu dis : « Toi, tu as l’air d’être une fana du manger sain. Je me trompe ? » Elle rit. Qu’est-ce qui marche ?', '["La supposition joueuse l’a impliquée et a tout de suite lancé un échange taquin", "Tu as montré ton assurance en faisant une affirmation audacieuse", "Tu l’as rendue curieuse de savoir pourquoi tu la voyais soucieuse de sa santé"]'::jsonb, 'Un rire plus une correction, c’est de l’implication ; reste dans ce ton joueur et développe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c36a094c-8b8b-4c97-b801-f551071a78ed', 'fr', 'Elle porte des vêtements vintage au style artistique. Quelle accroche utilise efficacement une supposition ?', '["« J’adore ton style. Tu fais tes courses où, d’habitude ? »", "« Tu as l’air de travailler dans un domaine créatif. Je me trompe ? »", "« Toi, tu chines en friperie, non ? »", "La supposition sur le métier créatif ou celle sur la friperie"]'::jsonb, 'Les deux l’obligent à s’impliquer pour confirmer, démentir ou expliquer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c387493a-0ebd-41c3-b083-1a639c5a593d', 'fr', 'Pourquoi t’excuser d’emblée affaiblit-il une accroche ?', '["Ça fait baisser ton statut", "Ça te présente comme un dérangement", "Ça lui donne le contrôle", "Toutes les réponses ci-dessus"]'::jsonb, 'T’excuser fait de toi un dérangement ; engage plutôt la conversation comme si tu étais à ta place.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3fe310a-e657-4693-8a1b-acee8218f2a8', 'fr', 'Quelle règle rend une accroche par supposition perspicace plutôt que lancée au hasard ?', '["La dire avec assurance", "La fonder sur ce que tu observes", "Rester vague", "La rendre provocante"]'::jsonb, 'Appuyer une supposition sur des signes visibles la rend réfléchie plutôt qu’arbitraire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c41c83a5-d2fe-4cdf-b37f-bcec922ef1d8', 'fr', '« Mon pote me trouve fou, mais moi, je pense que les gens qui… » Que fait cette accroche ?', '["Elle crée un débat où son avis compte pour trancher", "Elle montre ta personnalité et ton humour pour créer de l’attirance", "Elle la met sur ses gardes parce que tu la dragues"]'::jsonb, 'Un débat ou un dilemme sollicite son avis, ce qui la valorise et l’implique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4e94987-68b3-4c33-b481-27950bb88e63', 'fr', 'Dans quels lieux les accroches directes conviennent-elles le mieux ?', '["Les supermarchés", "Les bibliothèques calmes", "Les salles d’attente chez le médecin", "Les bars et les boîtes"]'::jsonb, 'Une intention directe convient aux lieux faits pour les rencontres, comme les bars et les boîtes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4ec10a6-7307-4d33-b4ac-bab091417d95', 'fr', 'Pourquoi t’excuser dans ton accroche t’empêche-t-il de donner le ton ?', '["Ça sous-entend que ce qu’elle faisait est plus important", "Ça demande la permission au lieu de mener", "Ça présente ta présence comme une interruption", "Ça montre que tu assumes pleinement le moment"]'::jsonb, 'T’excuser fait de toi une interruption, pas une option.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c728f4f6-0836-4faf-b386-b10c475ae132', 'fr', 'Pourquoi les accroches indirectes mettent-elles moins de pression que les directes ?', '["Elles déclarent tout de suite un intérêt amoureux", "Elles font passer l’approche pour un moment partagé ordinaire", "Elles laissent l’échange se développer naturellement", "Elles cachent l’intention derrière une remarque sur la situation"]'::jsonb, 'Une situation partagée rend l’entrée en matière attendue et facile à suivre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9f1e798-7318-4c31-b9db-3d51fbde0554', 'fr', 'Quelle est la raison principale pour laquelle les accroches par supposition créent de l’implication ?', '["Elles paraissent plus assurées que des questions", "Elles signalent tôt une intention amoureuse", "Elles l’obligent à répondre activement plutôt qu’en pilote automatique"]'::jsonb, 'Une supposition appelle une réponse. Elle est tout de suite impliquée pour corriger ou confirmer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cad92129-8727-4718-bff9-4ab66c366d32', 'fr', 'Pourquoi les accroches qui demandent son avis créent-elles une forte implication dès le départ ?', '["Elle sent que son point de vue est important", "Elles la présentent comme quelqu’un dont le jugement compte", "Elles sont utilitaires et vite expédiées", "Elles aident en valorisant ce qu’elle apporte"]'::jsonb, 'On réagit quand on se sent écouté et pris au sérieux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb1b3910-7f46-4638-b7ba-949483f7d10a', 'fr', 'Au bar. Vous êtes allés dans un coin plus calme. Et ensuite ?', '["Continuer la conversation et proposer de se revoir une autre fois", "Prendre ses coordonnées maintenant, tant que l’élan est fort", "Proposer d’aller ailleurs ensemble", "Prendre son numéro ou proposer de continuer ensemble ailleurs, selon l’organisation et ses signaux"]'::jsonb, 'Un élan fort appelle une étape suivante : prends ses coordonnées, ou propose de continuer ailleurs si ses signaux disent oui.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ccb554b7-2aa7-47d7-a64b-d4d9612a37a1', 'fr', 'Pourquoi certains angles et certaines distances d’approche créent-ils un malaise ?', '["Ils déclenchent des réactions automatiques face à une menace", "Ils bloquent ses mouvements ou ses sorties possibles", "Ils rendent ton intention invisible pendant l’approche", "Ils montrent toujours une grande assurance"]'::jsonb, 'Un mauvais angle et une mauvaise distance paraissent intrusifs, sans même passer par une décision consciente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cd75e2e6-d17a-4bb7-93e9-0f592f46fef8', 'fr', 'Pourquoi ton entrée en matière doit-elle être plus intéressante que ce qu’elle faisait avant ?', '["Sinon, elle y retournera", "Les humains sont programmés pour prêter attention à ce qui est intéressant", "Tu dois capter son attention face aux distractions", "Toutes les réponses ci-dessus"]'::jsonb, 'Tout est vrai : si ce que tu proposes n’est pas plus captivant que ce qu’elle faisait, elle y retourne.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ceadc18e-3007-4ed0-beba-55eb062fbd75', 'fr', 'La conversation se passe bien. Elle te demande d’où tu viens. Tu réponds, et ensuite ?', '["Lui poser une autre question pour continuer à mener", "Développer ta réponse pour continuer à parler", "La laisser poser la question suivante pour montrer que tu écoutes"]'::jsonb, 'Donner le ton, c’est faire avancer la conversation ; réponds, puis relance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cf063d07-0835-4825-9d56-79f6e3255038', 'fr', 'Tu lui dis que tu la trouves attirante. Elle te remercie, mais ses réponses restent courtes.', '["En rajouter pour montrer ton assurance", "Passer à une conversation légère pour détendre l’atmosphère", "Prendre congé poliment et la laisser à l’aise"]'::jsonb, 'Des réponses minimales après une intention claire veulent dire que l’intérêt n’est pas réciproque.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0ec47ae-1140-4d62-b956-39af81780946', 'fr', 'Quels comportements montrent que tu donnes bien le ton ?', '["Une certitude calme", "L’indécision", "Mener les transitions", "Avoir besoin de son accord"]'::jsonb, 'On donne le ton par la direction, pas par l’accord ; guide au lieu de vérifier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1f7d186-8772-4b75-bb24-e34679605860', 'fr', 'Vous promenez tous les deux vos chiens, qui se mettent à jouer. Qu’est-ce qui marche de façon indirecte ?', '["Commenter la façon dont les chiens s’entendent", "Complimenter son physique ou celui de son chien", "Lui demander de quelle race est son chien", "Lui demander si elle vient souvent dans ce parc"]'::jsonb, 'Rester sur l’expérience partagée laisse l’aisance s’installer naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3daff27-e652-43a8-8f20-af94b5be0f32', 'fr', 'Dans la rue. Elle est aimable, mais tu n’es pas sûr de son intérêt. Quelle est la meilleure chose à faire ?', '["Marcher à côté d’elle et continuer à parler", "Baisser ton énergie et t’aligner sur son rythme", "Dire « Tu as l’air cool. Ça te dirait qu’on prenne un café un de ces jours ? »"]'::jsonb, 'Une invitation simple lui permet de dire clairement oui ou non, sans forcer la suite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d43846a5-78ac-402f-95a0-7cfcb54078ce', 'fr', 'Après des réponses neutres, pourquoi vaut-il mieux clarifier que t’attarder ?', '["Ça lui donne un choix clair, oui ou non", "Ça abrège un moment gênant", "Ça l’oblige à révéler son attirance", "Ça évite d’avoir à deviner"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d466b22a-5014-4620-9cfa-19217d091ad6', 'fr', 'Quelles sont les accroches indirectes efficaces ?', '["Commenter le lieu", "Poser une question sur la situation que vous vivez tous les deux", "Remarquer une expérience partagée", "Complimenter son physique"]'::jsonb, 'Une situation partagée rend l’entrée en matière attendue et facile à suivre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d61d2413-5ee2-43c8-8cce-8d6030c1879e', 'fr', 'Qu’est-ce qui t’empêche de donner le ton dans une accroche ?', '["Faire une affirmation directe au lieu de demander la permission", "T’excuser de l’aborder ou de l’interrompre", "Lui demander d’abord si tu peux lui parler"]'::jsonb, 'T’excuser fait de toi un dérangement ; engage plutôt la conversation comme si tu étais à ta place.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d743d469-5774-4931-80b8-cf68fa8054d1', 'fr', 'Tu hésites 30 secondes, et quelqu’un d’autre l’aborde avant toi. Qu’est-ce qui a causé ça ?', '["Tu as laissé à ton cerveau le temps de t’en dissuader", "Il te manquait une bonne accroche", "Son désintérêt évident", "Tu ne te sentais pas assez prêt"]'::jsonb, 'Agir vite empêche le doute de s’installer. Bouge dans les trois secondes après l’avoir remarquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d76f2c05-59de-4480-a3a4-8dbe27fb2854', 'fr', 'Pourquoi la règle des trois secondes marche-t-elle ?', '["Elle te laisse le temps de préparer une accroche parfaite", "Elle te permet d’évaluer d’abord son intérêt", "Elle te fait agir avant que la détection des menaces ne crée de la résistance"]'::jsonb, 'La règle marche parce que tu agis avant que ton cerveau ne trouve des raisons de ne pas y aller.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('daf41a36-31b3-4cc7-b731-be0601f73a66', 'fr', 'Pourquoi les accroches qui éveillent la curiosité captent-elles mieux l’attention ?', '["Elles font baisser les défenses", "Elles créent une obligation", "Elles retardent le jugement", "Elles déclenchent l’intérêt"]'::jsonb, 'La curiosité marche parce qu’elle attire naturellement l’attention ; commence par quelque chose d’intrigant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc0ff18e-1928-43e2-b403-e3cb7a6b3ab2', 'fr', 'La conversation part sur un sujet ennuyeux. Donner le ton, c’est :', '["la suivre pour montrer que tu écoutes et que ça t’intéresse", "réorienter vers un sujet qui t’intéresse plus, sans rejeter le sien", "lui dire que tu préférerais parler d’autre chose"]'::jsonb, 'Réoriente en reconnaissant le moment et en allant vers des sujets plus énergiques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc4c48ee-7f80-40c8-8355-cfd7dfdf8159', 'fr', 'Au café, tu engages la conversation. Elle sourit chaleureusement, mais répond en quelques mots et se tourne ailleurs.', '["Ouverture : un sourire chaleureux montre de l’intérêt malgré des réponses brèves", "Politesse : elle sourit par gentillesse, mais son corps montre de la réserve", "Pas clair : des signaux mitigés demandent plus d’échange pour juger"]'::jsonb, 'Quand les réponses sont brèves et que la posture se détourne, respecte la limite et pars.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ddf26019-643c-48e3-99bd-8ed12168ae51', 'fr', 'Dans le train, tu vois une femme qui lit un livre que tu adores. Qu’est-ce qui garantit l’échec ?', '["L’aborder et te faire rejeter", "Hésiter et ne pas l’aborder du tout", "Attendre qu’elle parle en premier", "Sourire sans rien dire"]'::jsonb, 'L’inaction garantit zéro chance ; l’action crée des possibilités.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df7b348f-77a6-43b4-b9c2-72ba495cd148', 'fr', 'Elle sourit, répond et te pose une question en retour. Meilleure chose à faire ?', '["Aller vite plus loin", "Ralentir l’échange", "Lui faire un compliment", "Continuer naturellement"]'::jsonb, 'Quand elle te renvoie la balle, continue naturellement pour créer de l’élan sans forcer le rythme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0a819cd-0a51-464f-ae01-bb50bf45ca1b', 'fr', 'Tu dis bonjour. Elle te donne son prénom, soutient ton regard et te demande d’où tu viens.', '["Elle est ouverte et s’investit dans l’échange", "Elle est polie et suit les conventions sociales", "Elle récolte des informations pour décider plus tard"]'::jsonb, 'Donner son prénom en retour et poser des questions signale un intérêt actif, pas une politesse passive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b6a830-3f63-4d2b-b958-5db45a154beb', 'fr', 'Pourquoi prendre la politesse pour de l’ouverture est-il une erreur courante ?', '["Les hommes veulent voir de l’intérêt, alors ils surinterprètent la politesse", "On apprend aux femmes à être polies, et les hommes prennent ça pour de l’attirance", "Les signaux polis incluent des sourires et de la chaleur, que les hommes lisent comme de l’intérêt", "Toutes les réponses ci-dessus"]'::jsonb, 'Les signaux polis sont volontairement doux ; fie-toi plutôt à une attention qui dure et aux questions qu’elle te pose.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d6b84b-cc78-420d-8d46-30d10f8f2b0a', 'fr', 'Elle échange chaleureusement, te touche le bras, pose des questions, puis dit : « Mon Uber est là. »', '["Ouverture avec une limite de temps : prends ses coordonnées avant que l’Uber arrive", "Politesse : le contact et les questions étaient de la courtoisie avant un départ prévu", "Mitigé : elle a annoncé une contrainte de temps"]'::jsonb, 'Une forte implication plus une vraie contrainte de temps, c’est ton signal pour échanger vos numéros tout de suite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2a6f6e8-963f-4da4-bfc3-a9cc1b615ab4', 'fr', 'Quels comportements indiquent un intérêt réel ?', '["Elle répond brièvement, mais soutient ton regard", "Elle se tourne entièrement vers toi pour répondre", "Elle te pose des questions en retour ou nourrit la conversation"]'::jsonb, 'Quand elle s’investit par des questions et une posture ouverte, l’intérêt est là ; garde l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2e4a209-5fc0-4faf-a13c-67ed31a8a170', 'fr', 'Tu n’abordes que lors de sorties prévues, quand tu te sens prêt. Qu’est-ce que ça limite ?', '["Ta quantité totale d’entraînement et de tentatives", "Tes chances d’échanges parfaits", "Tes exigences sur ton apparence"]'::jsonb, 'Un effort sélectif garde une faible quantité d’approches, ce qui ralentit tes progrès.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3b36edc-fa81-4ae9-ba6b-80b396e930c4', 'fr', 'Qu’est-ce qui rend une supposition fausse efficace quand même ?', '["Elle va peut-être te corriger, et c’est déjà de l’implication", "Sa correction l’amène souvent à t’expliquer la vérité", "Te tromper montre ta vulnérabilité, ce qui crée la confiance"]'::jsonb, 'Une supposition fausse crée de l’implication par la correction et l’explication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e549d946-f5c9-48d5-8ed3-03653b7ab3b6', 'fr', 'Vous feuilletez tous les deux des livres dans une librairie calme. Quelle accroche réduit la pression ?', '["« Tu as l’air de beaucoup lire. »", "« Ça te va bien, un livre. »", "« Je peux avoir tes coordonnées ? »", "« Tu as lu quelque chose de bien ici, dernièrement ? »"]'::jsonb, 'Une expérience partagée sur le moment lance la conversation naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e5eae06f-7a14-4c9f-ab68-d799aa9f603d', 'fr', 'Elle répond positivement, mais dit : « Je dois retourner voir mes amies dans une seconde. » Que fais-tu ?', '["Une réponse ouverte veut dire : continue malgré la contrainte de temps", "Faire forte impression en peu de temps, puis la laisser partir", "Le respecter : en prendre acte, puis partir proprement ou échanger rapidement vos coordonnées"]'::jsonb, 'L’ouverture n’efface pas les limites de temps ; fais court ou passe vite à l’étape suivante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6f7a034-55b9-4303-a1f2-e70269b09f81', 'fr', 'Tu vois une femme avec des tatouages artistiques. Quelle accroche l’implique ?', '["« Salut, ça va ce soir ? »", "« Tu as l’air de travailler dans un domaine créatif. »", "« Tu fais quoi dans la vie ? »", "« Tu es jolie. »"]'::jsonb, 'Une supposition précise l’oblige à s’impliquer et à répondre personnellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea6aac0e-0b64-4be8-aa43-1990315262e0', 'fr', 'Tu dis : « Tu es belle, il fallait que je te dise bonjour. » Elle rougit, te remercie, mais répond en quelques mots.', '["La complimenter encore pour montrer ton intérêt", "La taquiner sur sa timidité pour la mettre à l’aise", "Partir avec élégance : peu de réciprocité après une accroche directe veut dire pas d’intérêt"]'::jsonb, 'Rougir peut être de la politesse. Des réponses courtes après une accroche directe veulent dire qu’elle n’est pas intéressée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed852bcc-77f4-436a-9582-103cc2537be6', 'fr', 'Tu dis : « Je t’ai vue et je voulais te dire bonjour. » Elle rit, te dit bonjour et te demande ce que tu fais dans la vie.', '["Elle est juste polie dans un cadre social", "Elle te renvoie la balle et elle est ouverte à la suite", "Elle est surprise et gagne du temps pour évaluer"]'::jsonb, 'Son rire et ses questions en retour montrent de la réciprocité et une vraie envie de continuer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f0dd9eca-d510-4237-8ce4-290954082900', 'fr', 'Quels éléments rendent ton entrée en matière plus intéressante que ce qu’elle fait ?', '["Des suppositions joueuses qui l’impliquent tout de suite", "Lui demander son avis sur quelque chose qui l’intéresse", "Être plus fort ou plus énergique que ce qui l’entoure"]'::jsonb, 'L’implication vient de la participation, pas du volume.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f17c4317-4ac6-4db1-838b-c39a93c3de0f', 'fr', 'Au bar. Elle est aimable, mais tu n’es pas sûr de son intérêt. Quelle est la meilleure chose à faire ?', '["Lui demander « Tu viens boire un verre ? »", "Faire un geste physique audacieux", "Poser des questions plus profondes pour créer du lien", "Attendre en silence de voir si elle relance"]'::jsonb, 'Une invitation simple lui permet de dire clairement oui ou non, sans forcer la suite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2b0e5af-f8e1-480b-aa9a-969dfa406d42', 'fr', 'Elle se tourne vers toi, sourit chaleureusement, répond en détail et arrange ses cheveux en parlant.', '["Très ouverte : se tourner, sourire, répondre en détail et toucher ses cheveux montrent tous de l’intérêt", "Politesse : elle est aimable, et le geste vers ses cheveux est une coïncidence", "Nervosité : l’échange la stresse, sans qu’elle soit forcément intéressée"]'::jsonb, 'Plusieurs signes positifs ensemble signalent l’ouverture ; continue.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2ebba26-20ab-4f42-bd4e-eda08aa656ef', 'fr', 'Pourquoi commencer par une excuse affaiblit-il l’échange ?', '["Un mauvais timing", "Une attirance faible", "Tu te présentes comme un dérangement", "Elle n’était pas célibataire"]'::jsonb, 'T’excuser fait de toi un dérangement ; engage plutôt la conversation comme si tu étais à ta place.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fb2737de-57ac-46ae-bfd8-662497358e2a', 'fr', 'Qu’est-ce qui rend le mystère efficace dans une entrée en matière ?', '["Elle ne sait pas ce que tu vas dire ensuite, ce qui crée de la curiosité et de l’attention", "Ça l’empêche de te ranger dans une case et de t’écarter vite", "Les femmes sont naturellement attirées par les hommes mystérieux"]'::jsonb, 'Le mystère éveille la curiosité pour la suite, ce qui capte l’attention.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbb58fb-2105-465e-9bb2-95117c0d4ee4', 'fr', 'Elle se tourne entièrement vers toi, sourit, mais dit : « Je n’ai pas trop envie de parler aux gens ce soir. »', '["Refus poli : malgré un langage corporel positif, ses mots montrent un désintérêt", "Test : elle veut voir si tu vas passer outre son objection", "Mitigé : son corps dit oui, ses mots disent non ; insiste en douceur"]'::jsonb, 'Un langage corporel poli ne l’emporte pas sur une limite exprimée ; prends-en acte et pars.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbdc05b-610e-4954-bace-34af89e1f619', 'fr', 'Après une accroche directe, elle rit brièvement, mais regarde aussitôt autour d’elle.', '["Monter en énergie pour récupérer son attention", "Lui demander son numéro avant que l’élan retombe", "Laisser l’échange se terminer naturellement"]'::jsonb, 'Le rire peut être de la politesse ; une attention partagée veut dire qu’il est temps de te retirer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff750d3c-1bf6-4368-bb6c-04dc1b70a29b', 'fr', 'Pourquoi une limite de temps marche-t-elle sur le plan psychologique ?', '["Le cerveau se détend quand le moment ne ressemble pas à un long engagement", "Elle baisse la garde en sachant qu’elle n’est pas coincée dans une conversation sans fin", "Ça crée une rareté qui te donne plus de valeur"]'::jsonb, 'Une limite enlève la peur d’être coincée, ce qui la met plus à l’aise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
